              </ol>            </div>          </div>        </div>        <div class="card">          <svg width="315" height="206" viewBox="0 0 315 206" fill="none" xmlns="http://www.w3.org/2000/svg">            <path d="M101.02 159.018C101.02 160.802 100.491 162.546 99.4995 164.029C98.5085 165.512 97.0998 166.668 95.4517 167.351C93.8036 168.034 91.99 168.212 90.2404 167.864C88.4908 167.516 86.8836 166.657 85.6222 165.396C84.3608 164.134 83.5017 162.527 83.1537 160.778C82.8057 159.028 82.9843 157.214 83.667 155.566C84.3497 153.918 85.5057 152.509 86.989 151.518C88.4723 150.527 90.2161 149.998 92 149.998C94.3922 149.998 96.6863 150.949 98.3779 152.64C100.069 154.332 101.02 156.626 101.02 159.018ZM92 63.4101C73.0589 63.4101 57.7255 77.165 57.7255 94.0767V97.6846C57.7255 99.1199 58.2957 100.496 59.3106 101.511C60.3255 102.526 61.702 103.096 63.1373 103.096C64.5726 103.096 65.9491 102.526 66.964 101.511C67.9789 100.496 68.549 99.1199 68.549 97.6846V94.0767C68.549 83.136 79.0659 74.2336 92 74.2336C104.934 74.2336 115.451 83.136 115.451 94.0767C115.451 105.018 104.934 113.92 92 113.92C90.5647 113.92 89.1882 114.49 88.1733 115.505C87.1584 116.52 86.5883 117.896 86.5883 119.332V126.547C86.5883 127.983 87.1584 129.359 88.1733 130.374C89.1882 131.389 90.5647 131.959 92 131.959C93.4353 131.959 94.8118 131.389 95.8267 130.374C96.8416 129.359 97.4118 127.983 97.4118 126.547V124.365C113.746 122.038 126.275 109.338 126.275 94.0767C126.275 77.165 110.941 63.4101 92 63.4101ZM184 112.116C184 130.312 178.604 148.099 168.495 163.228C158.386 178.358 144.018 190.15 127.207 197.113C110.396 204.076 91.898 205.898 74.0517 202.348C56.2055 198.798 39.8126 190.036 26.9462 177.17C14.0798 164.303 5.31764 147.911 1.7678 130.064C-1.78204 112.218 0.0398606 93.7199 7.00312 76.9091C13.9664 60.0983 25.7582 45.7298 40.8876 35.6208C56.0169 25.5117 73.8041 20.116 92 20.116C116.391 20.1446 139.775 29.8466 157.022 47.0938C174.269 64.3409 183.971 87.7248 184 112.116ZM173.176 112.116C173.176 96.060